function openFixedCostMonth(date){const api=window.MoneybrainFixedCosts,incomeApi=window.MoneybrainRecurringIncome,summary=api.month(date.getFullYear(),date.getMonth(),state.transactions),incomes=incomeApi.month(date.getFullYear(),date.getMonth(),state.transactions),incomeTotal=incomes.reduce((sum,item)=>sum+Number(item.expectedAmount),0),difference=incomeTotal-summary.expected,timeline=[...summary.rows.map(item=>({kind:'expense',date:item.due,item})),...incomes.map(item=>({kind:'income',date:item.due,item}))].sort((a,b)=>new Date(a.date)-new Date(b.date)||(a.kind==='income'?-1:1));open(`<div class="sheet-title"><div><span class="eyebrow">Monatsvorschau</span><h2>${capitalize(monthFmt.format(date))}</h2></div><button class="close">✕</button></div><section class="fixed-cost-summary month-flow-summary"><div><span>Fixkosten</span><strong class="negative">${euro.format(summary.expected)}</strong></div><div><span>Regelmäßige Einnahmen</span><strong class="positive">${euro.format(incomeTotal)}</strong></div><div><span>Differenz</span><strong class="${difference>=0?'positive':'negative'}">${difference>=0?'+':''}${euro.format(difference)}</strong></div></section><div class="section-title"><h2>Chronologischer Monatsverlauf</h2></div><div class="fixed-month-list">${timeline.length?timeline.map(entry=>entry.kind==='expense'?`<div class="fixed-month-entry month-flow-expense"><button data-edit-month-cost="${entry.item.id}"><span><strong>${escapeHtml(entry.item.name)}</strong><small>${new Date(entry.item.due).toLocaleDateString('de-DE')} · Fixkosten</small></span><b>− ${euro.format(entry.item.expected)}</b></button><button class="fixed-paid-toggle ${entry.item.paid?'paid':''}" data-month-paid="${entry.item.id}">${entry.item.paid?'✓ Bezahlt':'Als bezahlt markieren'}</button></div>`:`<div class="fixed-month-entry month-flow-income"><button data-edit-month-income="${entry.item.id}"><span><strong>${escapeHtml(entry.item.name)}</strong><small>${new Date(entry.item.due).toLocaleDateString('de-DE')} · Regelmäßiger Eingang</small></span><b>+ ${euro.format(entry.item.expectedAmount)}</b></button><button class="fixed-paid-toggle ${entry.item.received?'paid':''}" data-month-received="${entry.item.id}">${entry.item.received?'✓ Eingegangen':'Als eingegangen markieren'}</button></div>`).join(''):'<div class="empty">In diesem Monat sind keine regelmäßigen Zahlungen geplant.</div>'}</div>`);content.querySelectorAll('[data-edit-month-cost]').forEach(button=>button.onclick=()=>openFixedCostForm(api.all().find(item=>item.id===button.dataset.editMonthCost)));content.querySelectorAll('[data-edit-month-income]').forEach(button=>button.onclick=()=>openRecurringIncomeForm(incomeApi.all().find(item=>item.id===button.dataset.editMonthIncome)));content.querySelectorAll('[data-month-paid]').forEach(button=>button.onclick=()=>{const row=summary.rows.find(item=>item.id===button.dataset.monthPaid);api.setPaid(row.id,row.occurrence,!row.paid,row.expected);openFixedCostMonth(date);showToast(row.paid?'Als offen markiert':'Als bezahlt markiert')});content.querySelectorAll('[data-month-received]').forEach(button=>button.onclick=()=>{const row=incomes.find(item=>item.id===button.dataset.monthReceived);incomeApi.setReceived(row.id,row.occurrence,!row.received,row.expectedAmount);openFixedCostMonth(date);showToast(row.received?'Als offen markiert':'Als eingegangen markiert')})}
