 form.onsubmit=event=>{event.preventDefault();const data=new FormData(form),payload={name:String(data.get('name')).trim(),type:String(data.get('type')),includeInBudget:Boolean(data.get('includeInBudget')),active:Boolean(data.get('active'))};if(existing)accounts.update(existing.id,payload);else accounts.create(payload);sheet.close();state.route='money';render();showToast(existing?'Geldtopf aktualisiert':'Geldtopf angelegt')};
 content.querySelector('#reconcileAccount')?.addEventListener('click',()=>openReconciliation(existing));
